<?php require_once __DIR__ . '/includes/config.php';$p=db();if(!(int)$p->query('SELECT COUNT(*) FROM users')->fetchColumn()){$s=$p->prepare('INSERT INTO users(full_name,username,password_hash,role) VALUES(?,?,?,?)');foreach([['Administrator','admin','Admin123!','admin'],['HR Officer','hr_officer','HrOfficer123!','hr'],['Payroll Officer','payroll_officer','Payroll123!','payroll'],['Auditor','auditor','Auditor123!','auditor']] as $u)$s->execute([$u[0],$u[1],password_hash($u[2],PASSWORD_DEFAULT),$u[3]]);}
$s=$p->prepare('INSERT IGNORE INTO employees(employee_no,full_name,department,job_title,employment_status) VALUES(?,?,?,?,?)');foreach([['EMP001','John Kato','Finance','Accountant','active'],['EMP002','Mary Namusoke','HR','HR Officer','active'],['EMP003','Peter Okello','ICT','Analyst','inactive'],['EMP004','David Mugisha','Finance','Clerk','terminated']] as $r)$s->execute($r);
$ids=$p->query('SELECT employee_no,id FROM employees')->fetchAll();$m=[];foreach($ids as $r)$m[$r['employee_no']]=$r['id'];$s=$p->prepare('INSERT INTO payroll(employee_id,employee_no,pay_period,gross_amount,payment_reference,payment_date) VALUES(?,?,?,?,?,?)');foreach([['EMP001',3500000,'D001'],['EMP002',2800000,'D002'],['EMP003',2200000,'D003'],['EMP999',2500000,'D999'],['EMP004',1800000,'D004']] as $r){$q=$p->prepare('SELECT COUNT(*) FROM payroll WHERE payment_reference=?');$q->execute([$r[2]]);if(!(int)$q->fetchColumn())$s->execute([$m[$r[0]]??null,$r[0],'2026-11',$r[1],$r[2],'2026-11-30']);}echo 'Setup complete. Demo: admin / Admin123! Delete setup.php now. <a href="login.php">Login</a>';